// R2 (02-ui.md CMP-001, CMP-026, CMP-030, CMP-031): puts the chosen look on a companion SVG and draws the item tiles.
// Data: look-art-data.js (generated by tools/make-templates.mjs from fe-ui's item and plant files). DOM only, no state.
// The scaffold stores numbers (look-client.js): character 1/2/3 = honey/cotton/matcha, item 1/2/3 = the CMP-030 rows of that slot.
import { ITEM_SVG, PLANT_SVG, BODY_D } from './look-art-data.js';

export const CHARACTER_IDS = ['honey', 'cotton', 'matcha'];
export const ITEM_IDS = {
  head: ['straw-hat', 'beanie', 'daisy'],
  clothes: ['stripes', 'overalls', 'dots'],
  shoes: ['boots', 'sneakers', 'slippers'],
  accessory: ['scarf', 'bow', 'bell'],
};
export const characterId = (n) => CHARACTER_IDS[(Number(n) || 1) - 1] ?? 'honey';
const itemId = (slot, v) => (v === 'none' || v == null ? null : ITEM_IDS[slot][Number(v) - 1] ?? null);

// A paint reference to an element of the same SVG (kept out of one literal: tests/offline.test.js reads every CSS-like fragment as a file).
const fragRef = (id) => ['url(', '#', id, ')'].join('');
const NS = 'http://www.w3.org/2000/svg';
const LINE = '#2F2724';

// 02-ui.md §4 Anchors: head (x, y, r, s), neck (x, y, r, sx), left foot, right foot. The same for all three characters.
const ANCHOR = {
  neutral: { head: [200, 123.6, 0, 1], neck: [200, 246, 0, 1], l: [168, 302.8, 0, 1], r: [232, 302.8, 0, 1] },
  'pleasant-high': { head: [200, 86, 0, 0.98], neck: [200, 246, 0, 0.865], l: [166, 274, -18, 0.9], r: [234, 274, 18, 0.9] },
  'pleasant-low': { head: [228.5, 130.2, 9, 1.04], neck: [208.4, 256.6, 9, 1.037], l: [164, 306, 0, 1], r: [236, 306, 0, 1] },
  'unpleasant-high': { head: [200, 146, 0, 1.08], neck: [200, 262, 0, 1.054], l: [170, 306, 0, 0.94], r: [230, 306, 0, 0.94] },
  'unpleasant-low': { head: [200, 158, 0, 1.02], neck: [200, 280, 0, 1.041], l: [150, 312, 0, 1.04], r: [250, 312, 0, 1.04] },
};

// Placeholder-free markup: the strings come from our own files, never from the user.
function parse(markup) {
  const t = document.createElementNS(NS, 'svg');
  t.innerHTML = markup; // eslint-disable-line no-unsanitized/property
  return [...t.childNodes];
}
const g = (attrs, children = []) => {
  const el = document.createElementNS(NS, 'g');
  for (const [k, v] of Object.entries(attrs)) el.setAttribute(k, v);
  el.append(...children);
  return el;
};
const num = (n) => String(Math.round(n * 1000) / 1000);

// What goes into one slot (CMP-030 Placement). clipId = the id of this layer's clipPath.
function slotNodes(slot, id, mood, clipId, bodyD) {
  const a = ANCHOR[mood] ?? ANCHOR.neutral;
  const art = ITEM_SVG[`${slot}-${id}`];
  if (!art) return [];
  if (slot === 'head') {
    const [x, y, r, s] = a.head;
    return [g({ transform: `translate(${num(x)} ${num(y)}) rotate(${r}) scale(${s})`, class: 'slot-item' }, parse(art))];
  }
  if (slot === 'clothes') {
    const [x, y, r] = a.neck;
    const clipped = g({ 'clip-path': fragRef(clipId) }, [g({ transform: `translate(${num(x)} ${num(y)}) rotate(${r})`, class: 'slot-item' }, parse(art))]);
    const outline = document.createElementNS(NS, 'path'); // the clip eats the inner half of the 6 px line: draw it again
    outline.setAttribute('d', bodyD);
    outline.setAttribute('stroke', LINE); outline.setAttribute('stroke-width', '6'); outline.setAttribute('stroke-linejoin', 'round');
    return [g({ class: 'slot-item' }, [clipped, outline])];
  }
  if (slot === 'accessory') {
    const [x, y, r, sx] = a.neck;
    return [g({ transform: `translate(${num(x)} ${num(y)}) rotate(${r}) scale(${sx} 1)`, class: 'slot-item' }, parse(art))];
  }
  const [lx, ly, lr, ls] = a.l; const [rx, ry, rr, rs] = a.r; // shoes
  return [
    g({ transform: `translate(${lx} ${ly}) rotate(${lr}) scale(${ls})`, class: 'slot-item' }, parse(art)),
    g({ transform: `translate(${rx} ${ry}) rotate(${rr}) scale(${-rs} ${rs})`, class: 'slot-item' }, parse(art)),
  ];
}

const find = (svg, part) => svg.querySelector(`[id$="--${part}"]`);

// Fills one slot of one layer. animate: the new item fades in and scales 0.9 -> 1 from its anchor (CSS .slot-item--in, off with
// reduced motion), the old one fades out in 150 ms. Returns nothing.
export function fillSlot(svg, slot, value, mood, { animate = false, reduce = false } = {}) {
  const host = find(svg, `slot-${slot}`);
  if (!host) return;
  const clip = svg.querySelector('clipPath');
  const body = find(svg, 'body-fur');
  const old = [...host.childNodes];
  const fresh = itemId(slot, value) ? slotNodes(slot, itemId(slot, value), mood, clip?.id ?? '', body?.getAttribute('d') ?? BODY_D) : [];
  if (animate && !reduce && old.length) {
    const out = g({ class: 'slot-out' }, old);
    host.append(out);
    setTimeout(() => out.remove(), 150);
  } else old.forEach((n) => n.remove());
  if (animate && !reduce && fresh.length) host.append(g({ class: 'slot-in' }, fresh)); // wrapper: the fade must not replace an item's own transform
  else host.append(...fresh);
}

// The sprout, bud or flower of the stage (CMP-031): drops into slot-plant, stage coordinates.
export function fillPlant(svg, stage) {
  const host = find(svg, 'slot-plant');
  if (!host) return;
  host.replaceChildren(g({ class: 'slot-item' }, parse(PLANT_SVG[stage] ?? PLANT_SVG[1])));
}

// A freshly cloned layer: outfit, plant. (The growth size is CSS: .companion[data-stage] sets --g on #growth.)
export function dress(svg, mood, outfit, stage) {
  for (const slot of Object.keys(ITEM_IDS)) fillSlot(svg, slot, outfit?.[slot], mood);
  fillPlant(svg, stage);
}

// A copy of a layer's ids under another prefix (the phone preview): ids and clip-path references stay unique in the document.
export function reprefix(root, prefix) {
  for (const el of root.querySelectorAll('[id]')) el.id = prefix + el.id;
  for (const el of root.querySelectorAll('[clip-path]')) el.setAttribute('clip-path', fragRef(prefix + el.getAttribute('clip-path').slice(5, -1)));
}

// CMP-026: the 48 px tile art. The item on a faint Linen mannequin (the neutral body outline), one crop per slot. No ids.
const CROP = { head: '110 62 180 140', clothes: '100 150 200 160', shoes: '120 258 160 80', accessory: '120 196 160 100' };
let tileCount = 0;
export function tileSvg(slot, value) {
  const id = itemId(slot, value);
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', CROP[slot]); svg.setAttribute('width', '48'); svg.setAttribute('height', '48');
  svg.setAttribute('aria-hidden', 'true'); svg.setAttribute('focusable', 'false'); svg.setAttribute('fill', 'none');
  svg.classList.add('tile__art');
  if (!id) return svg;
  const man = document.createElementNS(NS, 'path');
  man.setAttribute('d', BODY_D); man.setAttribute('fill', '#E6DACA');
  let clipId = '';
  if (slot === 'clothes') { // the clip needs an id; one per tile keeps ids unique in the document
    clipId = `tile-clip-${++tileCount}`;
    const cp = document.createElementNS(NS, 'clipPath'); cp.id = clipId;
    const cpPath = document.createElementNS(NS, 'path'); cpPath.setAttribute('d', BODY_D);
    cp.append(cpPath); svg.append(cp);
  }
  svg.append(man, ...slotNodes(slot, id, 'neutral', clipId, BODY_D).map((n) => { n.classList.remove('slot-item'); return n; }));
  return svg;
}

// CMP-028: the 28 x 40 plant icon of the 成长 line (decorative): the stage's plant cropped from the stage coordinates.
export function plantIcon(stage) {
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', '82 266 48 72'); svg.setAttribute('width', '28'); svg.setAttribute('height', '40');
  svg.setAttribute('aria-hidden', 'true'); svg.setAttribute('focusable', 'false'); svg.setAttribute('fill', 'none');
  svg.classList.add('growth__plant');
  svg.append(g({ class: 'slot-item' }, parse(PLANT_SVG[stage] ?? PLANT_SVG[1])));
  return svg;
}

// CMP-025: the 88 px disc art = the character's neutral template (glow included, stage 3, nothing worn), ids prefixed so they
// stay unique in the document. No .companion__art class, so none of the part animations run.
let discCount = 0;
export function discArt(char) {
  const svg = document.getElementById(`mood-${char}-neutral`).content.querySelector('svg').cloneNode(true);
  svg.removeAttribute('class');
  svg.classList.add('disc__art');
  svg.setAttribute('width', '88'); svg.setAttribute('height', '88');
  reprefix(svg, `disc${++discCount}-`);
  return svg;
}
